static void drop(const MenuProfile&p,AbiArray&a,unsigned item){if(a.owner){auto*r=static_cast<int*>(a.owner);if(__atomic_load_n(r,__ATOMIC_RELAXED)>=0&&__atomic_sub_fetch(r,1,__ATOMIC_ACQ_REL)==0)p.deallocate(a.owner,item,8);}}
double PlaybackSampler::number(void*o,const char*n,double fallback)const{if(!o)return fallback;auto v=menu.property(o,n);bool ok=false;double x=menu.number(&v,&ok);menu.variant_destroy(&v);return ok&&std::isfinite(x)?x:fallback;}
bool PlaybackSampler::flag(void*o,const char*n)const{return number(o,n,0)!=0;}
UiText PlaybackSampler::text(void*o,const char*n)const{UiText out;if(!o)return out;auto v=menu.property(o,n);auto a=menu.string(&v);if(a.size>=0&&a.size<=256&&(a.data||!a.size))for(std::ptrdiff_t i=0;i<a.size;i++)out+=static_cast<const char16_t*>(a.data)[i];drop(menu,a,2);menu.variant_destroy(&v);return out;}
void PlaybackSampler::event(void*p){auto*b=static_cast<EventBinding*>(p);timespec t{};uint64_t at=b->self->wall;if(!clock_gettime(CLOCK_REALTIME,&t)&&t.tv_sec>=0)at=uint64_t(t.tv_sec)*1000+uint64_t(t.tv_nsec)/1000000;b->self->diagnostics.note(b->kind,at);}
void PlaybackSampler::destroyed(void*p){static_cast<PlaybackSampler*>(p)->model=nullptr;}
void PlaybackSampler::rootDestroyed(void*p){static_cast<PlaybackSampler*>(p)->receiver=nullptr;}
void PlaybackSampler::close(){for(auto*&w:watches){signal_unwatch(w);w=nullptr;}signal_unwatch(death);signal_unwatch(rootDeath);death=rootDeath=nullptr;model=receiver=nullptr;}
void PlaybackSampler::bind(void*next,void*root){if(next==model&&root==receiver&&death&&rootDeath)return;close();if(!next||!root)return;static const char*names[]={"browseClosed()","exitZoom()","exposingChanged()","screenEVFChanged()","screenBackChanged()","screenHDMIChanged()","currentItemModelChanged()","zoomedChanged()"};for(unsigned i=0;i<8;i++){bindings[i]={this,static_cast<PlaybackEvent>(i)};watches[i]=signal_watch(signals,next,root,names[i],event,&bindings[i],released);}death=signal_watch(signals,next,root,"destroyed(QObject*)",destroyed,this,released);rootDeath=signal_watch(signals,root,root,"destroyed(QObject*)",rootDestroyed,this,released);if(!death||!rootDeath){close();return;}model=next;receiver=root;}
void*PlaybackSampler::find(void*r,void*current,bool preview,unsigned&nodes,unsigned depth)const{if(!r||depth>64||++nodes>4096)return nullptr;if(preview){auto name=menu.name(r);const char16_t wanted[]=u"FlickablePreview_root";bool match=name.size==21&&name.data;for(int i=0;i<21&&match;i++)match=static_cast<const char16_t*>(name.data)[i]==wanted[i];drop(menu,name,2);if(match&&flag(r,"visible")&&stock_get_object(stock,r,"itemModel")==current)return r;}else if(stock_has(stock,r,"contentWidth")&&stock_has(stock,r,"contentX")&&stock_has(stock,r,"visibleArea"))return r;auto a=menu.children(r);void*found=nullptr;if(a.size>=0&&a.size<=4096&&(a.data||!a.size)){auto**items=static_cast<void**>(a.data);for(std::ptrdiff_t i=0;i<a.size&&!found;i++)found=find(items[i],current,preview,nodes,depth+1);}drop(menu,a,8);return found;}
bool PlaybackSampler::tick(void*root,const PlaybackAttachment&full,bool refresh,uint64_t mono,uint64_t at){wall=at;if(sampled&&mono>=lastSample&&mono-lastSample<500)return false;lastSample=mono;sampled=true;void*browse=find_named_item(menu,root,u"BrowseView_root");void*m=browse?stock_get_object(stock,browse,"viewModel"):nullptr;bind(m,root);PlaybackSnapshot s;s.refreshPending=refresh;s.browseActive=flag(m,"browseViewActive");s.zoomed=flag(m,"zoomed");s.screenBack=flag(m,"screenBack");s.screenEVF=flag(m,"screenEVF");s.exposing=flag(m,"exposing");void*current=m?stock_get_object(stock,m,"currentItemModel"):nullptr;s.currentPresent=current;s.modelWidth=number(current,"imageWidth");s.modelHeight=number(current,"imageHeight");unsigned nodes=0;void*preview=current?find(browse,current,true,nodes):nullptr;s.previewPresent=preview;nodes=0;void*flick=preview?find(preview,nullptr,false,nodes):nullptr;void*low=find_named_item(menu,preview,u"4kPreview");auto&d=s.display;d.previewState=text(preview,"state");using D=PlaybackDisplay;const char*fnames[]={"width","height","contentWidth","contentHeight","contentX","contentY"};for(unsigned i=0;i<6;i++)d.metrics[i]=number(flick,fnames[i]);d.metrics[D::PreviewWidth]=number(low,"width");d.metrics[D::PreviewHeight]=number(low,"height");d.metrics[D::PreviewStatus]=number(low,"status",-1);
 void*viewport=full.item();if(viewport&&preview&&menu_contains(menu,preview,viewport)){d.flags[D::FullPresent]=true;d.flags[D::FullVisible]=flag(viewport,"visible");d.flags[D::FullFrameHardware]=true;d.metrics[D::FullStatus]=static_cast<unsigned>(full.state().status());d.metrics[D::DecodeWidth]=s.modelWidth;d.metrics[D::DecodeHeight]=s.modelHeight;d.metrics[D::RegionRequests]=full.state().regionRequests;d.metrics[D::RegionReadyMs]=full.state().regionReadyMs;d.metrics[D::ReadyTiles]=full.state().readyTiles;d.metrics[D::FailedTiles]=full.state().failedTiles;void*image=full.active_image();d.metrics[D::PaintedWidth]=number(image,"paintedWidth");d.metrics[D::PaintedHeight]=number(image,"paintedHeight");if(flick&&abi->map_from_scene){AbiPoint p=abi->map_from_scene(viewport,abi->map_scene(flick,{0,0})),q=abi->map_from_scene(viewport,abi->map_scene(flick,{1,0}));double scale=std::hypot(q.x-p.x,q.y-p.y);if(scale>0&&std::isfinite(scale)){d.metrics[D::FullScale]=1/scale;d.metrics[D::EffectiveX]=p.x;d.metrics[D::EffectiveY]=p.y;}}}
 return diagnostics.sample(s,at);
}
